#include <iostream>
#include <vector>
#include <string>
#include <sstream>

using namespace std;

/**
 * Problem: 10600 - Network Connections
 * 
 * 解題思路：
 * 1. 這是一個典型的並查集 (Union-Find) 問題。
 * 2. 每個電腦看作一個節點，連接操作 (c i j) 即為合併集合。
 * 3. 查詢操作 (q i j) 即為檢查兩個節點是否屬於同一個集合。
 * 4. 需要處理多組測試資料，且每組資料內的操作數量不固定，使用 getline 讀取操作。
 */

struct DSU {
    vector<int> parent;
    DSU(int n) {
        parent.resize(n + 1);
        for (int i = 1; i <= n; ++i) parent[i] = i;
    }
    int find(int i) {
        if (parent[i] == i) return i;
        return parent[i] = find(parent[i]);
    }
    void unite(int i, int j) {
        int rootI = find(i);
        int rootJ = find(j);
        if (rootI != rootJ) parent[rootI] = rootJ;
    }
};

int main() {
    int T;
    if (!(cin >> T)) return 0;
    while (T--) {
        int n;
        cin >> n;
        cin.ignore();
        DSU dsu(n);
        int success = 0, fail = 0;
        string line;
        while (getline(cin, line) && !line.empty()) {
            stringstream ss(line);
            char type;
            int i, j;
            ss >> type >> i >> j;
            if (type == 'c') {
                dsu.unite(i, j);
            } else {
                if (dsu.find(i) == dsu.find(j)) success++;
                else fail++;
            }
        }
        cout << success << "," << fail << endl;
        if (T > 0) cout << endl;
    }
    return 0;
}
